    public Task<CalculationRunView> RecalculateAsync(TenantId tenant, Guid actor, Guid planVersionId, CancellationToken ct) => coordinator.ExecuteAsync(tenant, async (c, token) =>
    {
        var run = Guid.CreateVersion7(); await Exec(c, "insert into business_planning.planning_calculation_run(tenant_id,id,plan_version_id,state,input_watermark) values($1,$2,'Running','planning-inputs')", token, tenant.Value, run, planVersionId);
        var drivers = new List<(Guid Entity, DateOnly Period, string Key, decimal Amount, string Currency)>();
        await using (var command = Cmd(c, "select legal_entity_id,period_start,driver_key,volume*price,currency_code from business_planning.revenue_plan_driver where tenant_id=$1 and plan_version_id=$2", tenant.Value, planVersionId))
        await using (var reader = await command.ExecuteReaderAsync(token)) { while (await reader.ReadAsync(token)) drivers.Add((reader.GetGuid(0), reader.GetFieldValue<DateOnly>(1), reader.GetString(2), reader.GetDecimal(3), reader.GetString(4).Trim())); }
        foreach (var driver in drivers)
        {
            using var document = JsonDocument.Parse("{}"); var signature = Signature(driver.Entity, driver.Period, "Revenue", document.RootElement); var coordinate = await Scalar<Guid?>(c, "select id from business_planning.planning_coordinate where tenant_id=$1 and plan_version_id=$2 and legal_entity_id=$3 and period_start=$4 and metric_code='Revenue' and signature=$5", token, tenant.Value, planVersionId, driver.Entity, driver.Period, signature); var coordinateId = coordinate ?? Guid.CreateVersion7();
            if (coordinate is null) await Exec(c, "insert into business_planning.planning_coordinate(tenant_id,id,plan_version_id,legal_entity_id,period_start,metric_code,dimension_key,signature) values($1,$2,$3,$4,$5,'Revenue','{}'::jsonb,$6)", token, tenant.Value, coordinateId, planVersionId, driver.Entity, driver.Period, signature);
            await Exec(c, "insert into business_planning.planning_calculated_fact(tenant_id,id,coordinate_id,amount,currency_code,calculation_run_id,formula_code) values($1,$2,$3,$4,$5,$6,'Revenue.VolumeTimesPrice') on conflict(tenant_id,coordinate_id) do update set amount=excluded.amount,currency_code=excluded.currency_code,calculation_run_id=excluded.calculation_run_id,formula_code=excluded.formula_code", token, tenant.Value, Guid.CreateVersion7(), coordinateId, driver.Amount, driver.Currency, run);
            await Exec(c, "insert into business_planning.planning_calculation_trace(tenant_id,id,calculation_run_id,coordinate_id,formula_code,inputs,output_amount) values($1,$2,$3,$4,'Revenue.VolumeTimesPrice',$5::jsonb,$6)", token, tenant.Value, Guid.CreateVersion7(), run, coordinateId, Json(new { driver.Key, method = "volume*price" }), driver.Amount);
        }
        await Exec(c, "update business_planning.planning_calculation_run set state='Succeeded',completed_at=now() where tenant_id=$1 and id=$2", token, tenant.Value, run); return new CalculationRunView(run, planVersionId, "Succeeded", drivers.Count, DateTimeOffset.UtcNow, null);
    }, ct);

    public Task<BudgetAvailabilityView> AvailabilityAsync(TenantId tenant, Guid bucketId, CancellationToken ct) => coordinator.ExecuteAsync(tenant, async (c, token) =>
    {
        await using var command = Cmd(c, "select b.id,b.original_budget+b.revision_total+b.transfer_in-b.transfer_out,b.actual_total,b.commitment_total,b.precommitment_total,p.mode,p.threshold_percent from business_planning.budget_control_bucket b join business_planning.budget_control_policy p on p.tenant_id=b.tenant_id and p.id=b.policy_id where b.tenant_id=$1 and b.id=$2", tenant.Value, bucketId); await using var reader = await command.ExecuteReaderAsync(token); if (!await reader.ReadAsync(token)) throw new PlanningException("planning.bucket_not_found"); var current = reader.GetDecimal(1); var actual = reader.GetDecimal(2); var bucketCommitment = reader.GetDecimal(3); var bucketPrecommitment = reader.GetDecimal(4); var mode = reader.GetString(5); var threshold = reader.GetDecimal(6); await reader.CloseAsync(); var ownerReconciled = await Scalar<bool>(c, "select exists(select 1 from business_planning.budget_control_owner_reconciliation where tenant_id=$1 and bucket_id=$2 and state='Succeeded' and discrepancy_amount=0)", token, tenant.Value, bucketId); var sourcePrecommitment = ownerReconciled ? 0m : await Scalar<decimal>(c, "select coalesce(sum(amount) filter (where reservation_kind='Precommitment'),0) from business_planning.budget_reservation where tenant_id=$1 and bucket_id=$2 and state='Reserved'", token, tenant.Value, bucketId); var sourceCommitment = ownerReconciled ? 0m : await Scalar<decimal>(c, "select coalesce(sum(amount) filter (where reservation_kind='Commitment'),0) from business_planning.budget_reservation where tenant_id=$1 and bucket_id=$2 and state='Reserved'", token, tenant.Value, bucketId); var manualReserved = await Scalar<decimal>(c, "select coalesce(sum(amount) filter (where reservation_kind='Manual'),0) from business_planning.budget_reservation where tenant_id=$1 and bucket_id=$2 and state='Reserved'", token, tenant.Value, bucketId); var commitment = bucketCommitment + sourceCommitment; var precommitment = bucketPrecommitment + sourcePrecommitment; var available = current - actual - commitment - precommitment - manualReserved; return new BudgetAvailabilityView(bucketId, current, actual, commitment, precommitment, manualReserved, available, mode, current == 0 ? "Empty" : $"{(available / current * 100):0.##}%");
    }, ct);

