    public Task<FormulaView> CreateFormulaAsync(TenantId tenant, Guid actor, CreateFormulaRequest request, CancellationToken ct) => coordinator.ExecuteAsync(tenant, async (c, token) =>
    {
        if (string.IsNullOrWhiteSpace(request.Code) || string.IsNullOrWhiteSpace(request.Expression) || request.Expression.Length > 1000 || request.Expression.Any(ch => !(char.IsLetterOrDigit(ch) || " _+-*/().,".Contains(ch)))) throw new PlanningException("planning.formula_invalid");
        var graph = new Dictionary<string, IReadOnlyCollection<string>>(StringComparer.OrdinalIgnoreCase);
        await using (var existing = Cmd(c, "select f.code,d.dependency_code from business_planning.planning_formula f left join business_planning.planning_formula_dependency d on d.tenant_id=f.tenant_id and d.formula_id=f.id where f.tenant_id=$1 and f.model_version_id=$2 and f.active", tenant.Value, request.ModelVersionId))
        await using (var reader = await existing.ExecuteReaderAsync(token)) { while (await reader.ReadAsync(token)) { var code = reader.GetString(0); var dep = reader.IsDBNull(1) ? null : reader.GetString(1); if (!graph.ContainsKey(code)) graph[code] = new List<string>(); if (dep is not null) ((List<string>)graph[code]).Add(dep); } }
        graph[request.Code.Trim()] = request.Dependencies.Select(x => x.Trim()).Where(x => x.Length > 0).ToArray();
        PlanningFormulaEngine.EnsureAcyclic(graph);
        var id = Guid.CreateVersion7();
        await Exec(c, "insert into business_planning.planning_formula(tenant_id,id,model_version_id,code,expression,output_metric_code) values($1,$2,$3,$4,$5,$6)", token, tenant.Value, id, request.ModelVersionId, request.Code.Trim(), request.Expression.Trim(), request.OutputMetricCode.Trim());
        foreach (var dependency in graph[request.Code.Trim()]) await Exec(c, "insert into business_planning.planning_formula_dependency(tenant_id,id,formula_id,dependency_code) values($1,$2,$3,$4)", token, tenant.Value, Guid.CreateVersion7(), id, dependency);
        await Audit(c, tenant.Value, actor, "formula_created", id, token);
        return new FormulaView(id, request.ModelVersionId, request.Code.Trim(), request.Expression.Trim(), request.OutputMetricCode.Trim(), graph[request.Code.Trim()].ToArray(), true);
    }, ct);

