    private static async Task<BudgetCheckView> CheckBudgetInTransaction(ITransactionContext c, TenantId tenant, Guid actor, BudgetCheckRequest request, CancellationToken token)
    {
        if (request.ProposedAmount <= 0) throw new PlanningException("planning.amount_invalid");

        await using var cmd = Cmd(c, "select b.original_budget+b.revision_total+b.transfer_in-b.transfer_out as current_budget,b.actual_total,b.commitment_total,b.precommitment_total,p.mode,p.threshold_percent from business_planning.budget_control_bucket b join business_planning.budget_control_policy p on p.tenant_id=b.tenant_id and p.id=b.policy_id where b.tenant_id=$1 and b.id=$2 for update", tenant.Value, request.BucketId);
        await using var r = await cmd.ExecuteReaderAsync(token);
        if (!await r.ReadAsync(token)) throw new PlanningException("planning.bucket_not_found");
        var current = r.GetDecimal(0);
        var actual = r.GetDecimal(1);
        var commitment = r.GetDecimal(2);
        var precommitment = r.GetDecimal(3);
        var policy = r.GetString(4);
        await r.CloseAsync();

        var reserved = await Scalar<decimal>(c, "select coalesce(sum(amount),0) from business_planning.budget_reservation where tenant_id=$1 and bucket_id=$2 and state='Reserved'", token, tenant.Value, request.BucketId);
        var before = current - actual - commitment - precommitment - reserved;
        var existingReservation = request.Reserve
            ? await Scalar<Guid?>(c, "select id from business_planning.budget_reservation where tenant_id=$1 and source_module=$2 and source_document_id=$3 and source_line_id=$4 and source_version=$5 for update", token, tenant.Value, request.SourceModule, request.SourceDocumentId, request.SourceLineId, request.SourceVersion)
            : null;
        var incrementalAmount = existingReservation is null ? request.ProposedAmount : 0m;
        var after = before - incrementalAmount;
        var decision = policy switch
        {
            "None" => "Allow",
            "Warn" when after < 0 => "Warn",
            "RequireApproval" when after < 0 => "RequireApproval",
            "Block" when after < 0 => "Block",
            _ => "Allow"
        };
        if (decision == "Block" && !request.Reserve)
            return new BudgetCheckView(decision, request.BucketId, current, actual, commitment, request.ProposedAmount, before, after, $"{(current == 0 ? 0 : (current - before) / current * 100):0.##}%", ["planning.budget_insufficient"], null);

        var reservation = existingReservation;
        if (request.Reserve && decision != "Block" && reservation is null)
        {
            reservation = Guid.CreateVersion7();
            await Exec(c, "insert into business_planning.budget_reservation(tenant_id,id,bucket_id,source_module,source_document_id,source_line_id,source_version,amount) values($1,$2,$3,$4,$5,$6,$7,$8)", token, tenant.Value, reservation, request.BucketId, request.SourceModule, request.SourceDocumentId, request.SourceLineId, request.SourceVersion, request.ProposedAmount);
        }

        return new BudgetCheckView(decision, request.BucketId, current, actual, commitment, request.ProposedAmount, before, after, $"{(current == 0 ? 0 : (current - before) / current * 100):0.##}%", after < 0 ? ["planning.budget_threshold_exceeded"] : [], reservation);
    }

