    private sealed record OverrideSeed(Guid Id, Guid LegalEntityId, Guid PlanVersionId);
    private static async Task<TransferInfo?> ReadTransfer(ITransactionContext c, Guid tenant, Guid id, CancellationToken ct) { await using var cmd = Cmd(c, "select from_bucket_id,to_bucket_id,amount,state from business_planning.budget_transfer where tenant_id=$1 and id=$2", tenant, id); await using var r = await cmd.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct) || r.IsDBNull(0) || r.IsDBNull(1)) return null; return new TransferInfo(r.GetGuid(0), r.GetGuid(1), r.GetDecimal(2), r.GetString(3)); }
    private static async Task EnsureDraftAssumption(ITransactionContext c, Guid tenant, Guid id, CancellationToken ct) { var state = await Scalar<string>(c, "select v.state from business_planning.planning_assumption a join business_planning.plan_version v on v.tenant_id=a.tenant_id and v.id=a.plan_version_id where a.tenant_id=$1 and a.id=$2", ct, tenant, id); if (state is null) throw new PlanningException("planning.assumption_not_found"); if (state != "Draft") throw new PlanningException("planning.version_immutable"); }
    private static async Task<PlanningCycleView?> GetCycle(ITransactionContext c, Guid tenant, Guid id, CancellationToken ct) { await using var cmd = Cmd(c, "select id,legal_entity_id,name,cycle_type,horizon,start_period,end_period,actual_cutoff,state,row_version from business_planning.planning_cycle where tenant_id=$1 and id=$2", tenant, id); await using var r = await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? ReadCycle(r) : null; }
    private static PlanningCycleView ReadCycle(NpgsqlDataReader r) => new(r.GetGuid(0), r.GetGuid(1), r.GetString(2), r.GetString(3), r.GetString(4), r.GetFieldValue<DateOnly>(5), r.GetFieldValue<DateOnly>(6), r.IsDBNull(7) ? null : r.GetFieldValue<DateOnly>(7), r.GetString(8), r.GetInt64(9));
    private static async Task<PlanVersionView?> GetPlanVersion(ITransactionContext c, Guid tenant, Guid id, CancellationToken ct) { await using var cmd = Cmd(c, "select id,cycle_id,model_version_id,name,version_kind,state,actual_cutoff,row_version from business_planning.plan_version where tenant_id=$1 and id=$2", tenant, id); await using var r = await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? new(r.GetGuid(0), r.GetGuid(1), r.GetGuid(2), r.GetString(3), r.GetString(4), r.GetString(5), r.IsDBNull(6) ? null : r.GetFieldValue<DateOnly>(6), r.GetInt64(7)) : null; }
    private static async Task<ScenarioView?> ReadScenario(ITransactionContext c, Guid tenant, Guid id, CancellationToken ct) { await using var cmd = Cmd(c, "select id,name,scenario_type,visibility,state from business_planning.scenario where tenant_id=$1 and id=$2", tenant, id); await using var r = await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct) ? new(r.GetGuid(0), r.GetString(1), r.GetString(2), r.GetString(3), r.GetString(4)) : null; }
    private static async Task Audit(ITransactionContext c, Guid tenant, Guid actor, string action, Guid entity, CancellationToken ct) { await Exec(c, "insert into business_planning.planning_audit_event(tenant_id,id,actor_user_id,action,entity_id) values($1,$2,$3,$4,$5)", ct, tenant, Guid.CreateVersion7(), actor, action, entity); }
    private static async Task<T?> Scalar<T>(ITransactionContext c, string sql, CancellationToken ct, params object?[] values) { await using var cmd = Cmd(c, sql, values); var value = await cmd.ExecuteScalarAsync(ct); if (value is null or DBNull) return default; var target = Nullable.GetUnderlyingType(typeof(T)) ?? typeof(T); if (target == typeof(Guid)) return (T)(object)(Guid)value; if (target == typeof(DateOnly)) return (T)(object)(DateOnly.FromDateTime((DateTime)value)); return (T)Convert.ChangeType(value, target, CultureInfo.InvariantCulture); }
    private static async Task Exec(ITransactionContext c, string sql, CancellationToken ct, params object?[] values) { await using var cmd = Cmd(c, sql, values); await cmd.ExecuteNonQueryAsync(ct); }
    private static NpgsqlCommand Cmd(ITransactionContext c, string sql, params object?[] values) { var cmd = new NpgsqlCommand(sql, c.Connection, c.Transaction); for (var i = 0; i < values.Length; i++) { var isJson = values[i] is JsonDocument or JsonElement || (values[i] is string text && text.StartsWith('{') && sql.Contains("jsonb", StringComparison.OrdinalIgnoreCase)); var p = cmd.Parameters.AddWithValue(values[i] ?? DBNull.Value); if (isJson) p.NpgsqlDbType = NpgsqlDbType.Jsonb; } return cmd; }
    private static object Db(object? value) => value ?? DBNull.Value;
    private static string Json(JsonElement value) => value.GetRawText();
    private static string Json(object value) => JsonSerializer.Serialize(value);
    private static string Signature(Guid entity, DateOnly period, string metric, JsonElement key) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes($"{entity:D}|{period:yyyy-MM-dd}|{metric}|{key.GetRawText()}"))).ToLowerInvariant();
}
